        this.inputFirstRep.inputEl.focus();
        this.inputFirstRep.inputEl.select();
        //
        // Priority
        let pMin = this.plugin.settings.defaultPriorityMin;
        let pMax = this.plugin.settings.defaultPriorityMax;
        contentEl.appendText("Priority: ");
